package com.example.examplemod.client;

import com.example.examplemod.CreateCityExpansionCore;
import com.example.examplemod.steel.SteelConverterMultiblock;
import com.example.examplemod.steel.SteelConverterMultiblock.ExpectedBlock;
import com.mojang.blaze3d.vertex.*;
import net.minecraft.client.Minecraft;
import net.minecraft.client.renderer.*;
import net.minecraft.core.*;
import net.minecraft.network.chat.Component;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.block.state.properties.BlockStateProperties;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.neoforge.client.event.*;
import java.util.*;

public final class SteelConverterGuideRenderer {
    private static final int ALL=-1; private static BlockPos controller; private static int layer,lastLayer,cooldown;
    private SteelConverterGuideRenderer(){}
    public static void toggle(BlockPos pos){CokeBatteryGuideRenderer.hide(false);BlastFurnaceGuideRenderer.hide(false);if(pos.equals(controller)){hide(true);return;}controller=pos.immutable();layer=lastLayer=cooldown=0;announce(false);}
    public static void hide(boolean announce){boolean shown=controller!=null;controller=null;if(announce&&shown&&Minecraft.getInstance().player!=null)Minecraft.getInstance().player.displayClientMessage(Component.translatable("message.createcityexpansioncore.steel_guide.disabled"),true);}
    @SubscribeEvent public static void tick(ClientTickEvent.Post e){if(controller==null)return;while(BuildGuideKeyMappings.consumeNext())change(1);while(BuildGuideKeyMappings.consumePrevious())change(-1);while(BuildGuideKeyMappings.consumeAll())all();if(++cooldown>=20){cooldown=0;nearest();}}
    private static void change(int d){int base=layer==ALL?lastLayer:layer;layer=Math.floorMod(base+d,SteelConverterMultiblock.HEIGHT);lastLayer=layer;announce(false);}
    private static void all(){if(layer==ALL)layer=lastLayer;else{lastLayer=layer;layer=ALL;}announce(false);}
    @SubscribeEvent public static void render(RenderLevelStageEvent e){if(e.getStage()!=RenderLevelStageEvent.Stage.AFTER_TRANSLUCENT_BLOCKS||controller==null)return;var mc=Minecraft.getInstance();if(mc.level==null)return;BlockState cs=mc.level.getBlockState(controller);if(!cs.is(CreateCityExpansionCore.STEEL_CONVERTER_CONTROLLER.get())||!cs.hasProperty(BlockStateProperties.HORIZONTAL_FACING)){hide(false);return;}Direction f=cs.getValue(BlockStateProperties.HORIZONTAL_FACING);BlockPos o=SteelConverterMultiblock.getOrigin(controller,f);PoseStack pose=e.getPoseStack();MultiBufferSource.BufferSource src=mc.renderBuffers().bufferSource();VertexConsumer lines=src.getBuffer(RenderType.lines());var cam=e.getCamera().getPosition();pose.pushPose();pose.translate(-cam.x,-cam.y,-cam.z);int min=layer==ALL?0:layer,max=layer==ALL?SteelConverterMultiblock.HEIGHT-1:layer;for(int y=min;y<=max;y++)for(int z=0;z<SteelConverterMultiblock.DEPTH;z++)for(int x=0;x<SteelConverterMultiblock.WIDTH;x++){ExpectedBlock expected=SteelConverterMultiblock.expectedAt(x,y,z);BlockPos w=SteelConverterMultiblock.getWorldPosition(o,f,x,y,z);BlockState actual=mc.level.getBlockState(w);if(!SteelConverterMultiblock.matches(actual,expected))BuildGuideRenderHelper.renderOutline(pose,lines,w,status(expected,actual));}pose.popPose();src.endBatch(RenderType.lines());}
    private static BuildGuideRenderHelper.Status status(ExpectedBlock e,BlockState a){if(e==ExpectedBlock.AIR)return BuildGuideRenderHelper.Status.OCCUPIED_AIR;if(!a.isAir())return BuildGuideRenderHelper.Status.WRONG;return functional(e)?BuildGuideRenderHelper.Status.FUNCTIONAL:BuildGuideRenderHelper.Status.MISSING;}
    private static boolean functional(ExpectedBlock e){return e==ExpectedBlock.CONTROLLER||e==ExpectedBlock.FLUID_INPUT||e==ExpectedBlock.ITEM_INPUT||e==ExpectedBlock.FLUID_OUTPUT||e==ExpectedBlock.POWER_PORT||e==ExpectedBlock.BLOWER;}
    private static void announce(boolean bar){var mc=Minecraft.getInstance();if(mc.player==null||mc.level==null||controller==null)return;Counts c=counts(mc);Component l=layer==ALL?Component.translatable("message.createcityexpansioncore.build_guide.all_layers"):Component.literal("Y="+layer);mc.player.displayClientMessage(Component.translatable("message.createcityexpansioncore.steel_guide.enabled",l,c.correct,c.required,c.errors),bar);}
    private static void nearest(){var mc=Minecraft.getInstance();if(mc.player==null||mc.level==null||controller==null)return;BlockState cs=mc.level.getBlockState(controller);if(!cs.hasProperty(BlockStateProperties.HORIZONTAL_FACING))return;Direction f=cs.getValue(BlockStateProperties.HORIZONTAL_FACING);BlockPos o=SteelConverterMultiblock.getOrigin(controller,f);Target best=null;Map<ExpectedBlock,Integer> left=new EnumMap<>(ExpectedBlock.class);int min=layer==ALL?0:layer,max=layer==ALL?SteelConverterMultiblock.HEIGHT-1:layer;for(int y=min;y<=max;y++)for(int z=0;z<SteelConverterMultiblock.DEPTH;z++)for(int x=0;x<SteelConverterMultiblock.WIDTH;x++){ExpectedBlock e=SteelConverterMultiblock.expectedAt(x,y,z);BlockPos w=SteelConverterMultiblock.getWorldPosition(o,f,x,y,z);if(SteelConverterMultiblock.matches(mc.level.getBlockState(w),e))continue;left.merge(e,1,Integer::sum);double d=mc.player.distanceToSqr(w.getCenter());if(best==null||d<best.distance)best=new Target(new SteelConverterMultiblock.LocalPos(x,y,z),w,e,d);}if(best==null){announce(true);return;}Component name=best.expected==ExpectedBlock.AIR?Component.translatable("message.createcityexpansioncore.build_guide.required_air"):SteelConverterMultiblock.requiredBlock(best.expected).getName();mc.player.displayClientMessage(Component.translatable("message.createcityexpansioncore.build_guide.target",name,best.local.x(),best.local.y(),best.local.z(),best.world.getX(),best.world.getY(),best.world.getZ(),left.getOrDefault(best.expected,0)),true);}
    private static Counts counts(Minecraft mc){BlockState cs=mc.level.getBlockState(controller);if(!cs.hasProperty(BlockStateProperties.HORIZONTAL_FACING))return new Counts(0,0,1);Direction f=cs.getValue(BlockStateProperties.HORIZONTAL_FACING);BlockPos o=SteelConverterMultiblock.getOrigin(controller,f);int c=0,r=0,e=0;for(int y=0;y<SteelConverterMultiblock.HEIGHT;y++)for(int z=0;z<SteelConverterMultiblock.DEPTH;z++)for(int x=0;x<SteelConverterMultiblock.WIDTH;x++){ExpectedBlock ex=SteelConverterMultiblock.expectedAt(x,y,z);if(ex!=ExpectedBlock.AIR)r++;if(SteelConverterMultiblock.matches(mc.level.getBlockState(SteelConverterMultiblock.getWorldPosition(o,f,x,y,z)),ex)){if(ex!=ExpectedBlock.AIR)c++;}else e++;}return new Counts(c,r,e);}
    private record Counts(int correct,int required,int errors){} private record Target(SteelConverterMultiblock.LocalPos local,BlockPos world,ExpectedBlock expected,double distance){}
}
